import os
import json
from composio import Composio

def main():
    # Initialize Composio
    composio_client = Composio()
    user_id = 'zealt-user01'

    # Step 1: Create a Trigger
    print("Creating trigger...")
    try:
        trigger = composio_client.triggers.create(
            slug='GITHUB_ISSUE_CREATED_TRIGGER',
            user_id=user_id,
            trigger_config={
                'owner': 'composiohq',
                'repo': 'composio',
                'state': 'open'
            }
        )
        print(f"Trigger created: {trigger}")
    except Exception as e:
        print(f"Trigger setup note: {e}")

    # Step 2: Handle Events
    sub = composio_client.triggers.subscribe()

    @sub.handle(trigger_slug='GITHUB_ISSUE_CREATED_TRIGGER')
    def handle_issue(event):
        try:
            payload = event.payload
            issue_body = payload.get('body', '')
            issue_number = payload.get('number')
            owner = payload.get('repository_owner', 'composiohq')
            repo = payload.get('repository_name', 'composio')

            print(f"Received new issue #{issue_number}")

            # Step 3: Analyze Sentiment via Workbench
            code = f"""
import json
from textblob import TextBlob

body = {repr(issue_body)}
sentiment = "neutral"

try:
    blob = TextBlob(body)
    if blob.sentiment.polarity < -0.1:
        sentiment = "negative"
except ImportError:
    # simple heuristic fallback
    negative_words = ['urgent', 'broken', 'error', 'fail', 'crash', 'terrible', 'bad', 'issue', 'bug']
    if any(w in body.lower() for w in negative_words):
        sentiment = "negative"

if sentiment == "negative":
    print("Sentiment is negative, adding urgent label.")
    result, error = run_composio_tool(
        tool_slug='GITHUB_ADD_LABELS_TO_AN_ISSUE',
        arguments={{
            'owner': '{owner}',
            'repo': '{repo}',
            'issue_number': {issue_number},
            'labels': ['urgent']
        }}
    )
    print("Added urgent label:", result, error)
else:
    print("Sentiment is not negative. No label added.")
"""

            session = composio_client.create(user_id=user_id)
            response = session.execute(
                'COMPOSIO_REMOTE_WORKBENCH',
                arguments={'code_to_execute': code}
            )
            print("Workbench execution response:", response)
        except Exception as e:
            print(f"Error handling event: {e}")

    print("Pipeline active")
    sub.wait_forever()

if __name__ == "__main__":
    main()

